def paginate(items, page, size):
    """Returns the items of one page. Pages start at 1."""
    if page < 1 or size < 1:
        raise ValueError("page and size must be at least 1")
    start = (page - 1) * size
    return items[start:start + size]

files.tests/test_paging.py:
from paging import paginate


def test_first_page():
    assert paginate([1, 2, 3, 4, 5, 6, 7], 1, 3) == [1, 2, 3]


def test_second_page():
    assert paginate([1, 2, 3, 4, 5, 6, 7], 2, 3) == [4, 5, 6]


def test_last_page_is_complete():
    assert paginate([1, 2, 3, 4, 5], 2, 3) == [4, 5]


def test_exact_last_page():
    assert paginate([1, 2, 3, 4, 5, 6], 2, 3) == [4, 5, 6]


def test_past_the_end_is_empty():
    assert paginate([1, 2, 3, 4, 5], 3, 3) == []


def test_page_zero_raises():
    import pytest
    with pytest.raises(ValueError):
        paginate([1, 2, 3], 0, 3)


def test_size_below_one_raises():
    import pytest
    with pytest.raises(ValueError):
        paginate([1, 2, 3], 1, 0)

